/**
 * Unit tests for FitnessFunction.isFeasible method.
 * Note: Since 'boundaries' is a private field in the inner class, 
 * reflection is used to manipulate it for testing coverage.
 */
public class FitnessFunction_isFeasible_TriageGen2Test {

    private CMAESOptimizer.FitnessFunction fitnessFunction;

    @Before
    public void setUp() {
        fitnessFunction = new CMAESOptimizer.FitnessFunction();
    }

    /**
     * Helper method to set the private 'boundaries' field via reflection.
     */
    private void setBoundaries(Object target, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField("boundaries");
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testIsFeasible_BoundariesIsNull() throws Exception {
        // Coverage for: if (boundaries == null) return true;
        setBoundaries(fitnessFunction, null);
        double[] x = {0.5, 0.5};
        assertTrue("Should return true when boundaries is null", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_AllValuesInRange() throws Exception {
        // Coverage for: loop completing and returning true
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {0.0, 0.5, 1.0};
        assertTrue("Should return true when all elements are within [0, 1]", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_ValueTooSmall() throws Exception {
        // Coverage for: if (x[i] < 0) return false;
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {0.5, -0.1, 0.5};
        assertFalse("Should return false when an element is less than 0", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_ValueTooLarge() throws Exception {
        // Coverage for: if (x[i] > 1.0) return false;
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {0.5, 1.1, 0.5};
        assertFalse("Should return false when an element is greater than 1.0", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_EmptyArray() throws Exception {
        // Coverage for: loop not executing
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {};
        assertTrue("Should return true for an empty array", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_BoundaryValues() throws Exception {
        // Coverage for: exactly 0 and exactly 1.0
        setBoundaries(fitnessFunction, new double[]{0, 1});
        double[] x = {0.0, 1.0};
        assertTrue("Should return true for boundary values 0.0 and 1.0", fitnessFunction.isFeasible(x));
    }
}
